// AUTO-GENERATED by scripts/build-sunburst-views.mjs — do not edit by hand.
// Sunburst apartments (floor*100 + unit-position) that have a courtyard
// panorama. Apartments without one are absent, so they're hidden from the
// floor dropdown in the apartment view.
export const SUNBURST_VIEW_APTS = [101, 201, 203, 204, 303, 304, 404, 603, 604, 803, 1004, 1104, 1304]

const VIEW_SET = new Set(SUNBURST_VIEW_APTS)

// Apartment number for a floor + unit position (1-8).
export const aptNumber = (floor, position) => floor * 100 + position

// Public path to a panorama, or null when that apartment has no view.
export const viewImage = (floor, position) =>
  VIEW_SET.has(aptNumber(floor, position))
    ? `/unit/views/sunburst/${aptNumber(floor, position)}.webp`
    : null

// Floors (ascending) where the given unit position has a panorama.
export const floorsForPosition = (position) =>
  SUNBURST_VIEW_APTS.filter((a) => a % 100 === position).map((a) =>
    Math.floor(a / 100),
  )
